package io.github.describeadmin.codegen.model;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

class FieldTypeMutaGate1Test {

    private static void check(FieldType t, String key, String simple, String importName,
                              String sql, boolean length, boolean precision) {
        assertEquals(key, t.key(), t + " key");
        assertEquals(simple, t.javaSimpleType(), t + " simple type");
        if (importName == null) {
            assertNull(t.importName(), t + " import");
        } else {
            assertEquals(importName, t.importName(), t + " import");
        }
        assertEquals(sql, t.sqlType(), t + " sql type");
        assertEquals(length, t.needsLength(), t + " needsLength");
        assertEquals(precision, t.needsPrecision(), t + " needsPrecision");
    }

    @Test
    void constructorMapsEveryConstantToItsDeclaredAttributes() {
        assertEquals(8, FieldType.values().length);
        check(FieldType.STRING, "string", "String", null, "VARCHAR", true, false);
        check(FieldType.TEXT, "text", "String", null, "TEXT", false, false);
        check(FieldType.INT, "int", "Integer", null, "INT", false, false);
        check(FieldType.LONG, "long", "Long", null, "BIGINT", false, false);
        check(FieldType.DECIMAL, "decimal", "BigDecimal", "java.math.BigDecimal", "DECIMAL", false, true);
        check(FieldType.FLAG, "flag", "Integer", null, "TINYINT", false, false);
        check(FieldType.DATE, "date", "LocalDate", "java.time.LocalDate", "DATE", false, false);
        check(FieldType.DATETIME, "datetime", "LocalDateTime", "java.time.LocalDateTime", "DATETIME", false, false);
    }
}

package io.github.describeadmin.codegen.model;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.Map;
import org.junit.jupiter.api.Test;

class FieldTypeMutaGate2Test {

    @Test
    void javaSimpleTypeStripsPackageForQualifiedTypesAndKeepsPlainNames() {
        Map<FieldType, String> expected = Map.of(
                FieldType.STRING, "String",
                FieldType.TEXT, "String",
                FieldType.INT, "Integer",
                FieldType.LONG, "Long",
                FieldType.DECIMAL, "BigDecimal",
                FieldType.FLAG, "Integer",
                FieldType.DATE, "LocalDate",
                FieldType.DATETIME, "LocalDateTime");

        for (FieldType type : FieldType.values()) {
            assertEquals(expected.get(type), type.javaSimpleType(), "simple type of " + type);
        }
        assertEquals(expected.size(), FieldType.values().length);
    }
}

package io.github.describeadmin.codegen.model;

import org.junit.jupiter.api.Test;

import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

class FieldTypeMutaGate3Test {

    @Test
    void ofLooksUpKeyCaseInsensitivelyAndRejectsUnknownOrNull() {
        // every type is found by its own key, and the exact same constant is returned
        for (FieldType t : FieldType.values()) {
            assertSame(t, FieldType.of(t.key()).orElseThrow());
            assertSame(t, FieldType.of(t.key().toUpperCase()).orElseThrow());
        }

        // mixed case
        assertEquals(Optional.of(FieldType.DATETIME), FieldType.of("DateTime"));
        assertEquals(Optional.of(FieldType.FLAG), FieldType.of("fLaG"));

        // enum constant name differs from key for none, but unknown keys must be empty
        assertTrue(FieldType.of("timestamp").isEmpty());
        assertTrue(FieldType.of("boolean").isEmpty());
        assertTrue(FieldType.of("json").isEmpty());
        assertTrue(FieldType.of("").isEmpty());

        // no trimming and no partial matching
        assertFalse(FieldType.of(" string").isPresent());
        assertFalse(FieldType.of("string ").isPresent());
        assertFalse(FieldType.of("str").isPresent());
        assertFalse(FieldType.of("dateX").isPresent());

        // null key is tolerated (equalsIgnoreCase(null) is false)
        assertTrue(FieldType.of(null).isEmpty());
    }
}

package io.github.describeadmin.codegen.model;

import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class FieldTypeMutaGate4Test {

    @Test
    void allKeysListsEveryKeyInDeclarationOrderAndIsImmutable() {
        List<String> keys = FieldType.allKeys();

        assertEquals(
                List.of("string", "text", "int", "long", "decimal", "flag", "date", "datetime"),
                keys);
        assertEquals(FieldType.values().length, keys.size());
        assertEquals(keys.size(), new HashSet<>(keys).size());

        for (FieldType t : FieldType.values()) {
            assertEquals(t.key(), keys.get(t.ordinal()));
            assertTrue(FieldType.of(keys.get(t.ordinal())).isPresent());
        }

        for (String forbidden : Arrays.asList("timestamp", "json", "boolean")) {
            assertFalse(keys.contains(forbidden));
        }

        assertThrows(UnsupportedOperationException.class, () -> keys.add("extra"));
        assertThrows(UnsupportedOperationException.class, () -> keys.remove(0));
    }
}

package io.github.describeadmin.codegen.model;

import org.junit.jupiter.api.Test;

import java.util.LinkedHashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class FieldTypeMutaGate5Test {

    @Test
    void keyReturnsExpectedLowercaseIdentifierForEveryConstant() {
        Map<FieldType, String> expected = new LinkedHashMap<>();
        expected.put(FieldType.STRING, "string");
        expected.put(FieldType.TEXT, "text");
        expected.put(FieldType.INT, "int");
        expected.put(FieldType.LONG, "long");
        expected.put(FieldType.DECIMAL, "decimal");
        expected.put(FieldType.FLAG, "flag");
        expected.put(FieldType.DATE, "date");
        expected.put(FieldType.DATETIME, "datetime");

        assertEquals(FieldType.values().length, expected.size());

        for (Map.Entry<FieldType, String> e : expected.entrySet()) {
            String key = e.getKey().key();
            assertEquals(e.getValue(), key);
            assertEquals(key.toLowerCase(), key);
            assertTrue(FieldType.of(key).isPresent());
            assertEquals(e.getKey(), FieldType.of(key).get());
        }
    }
}

